<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { buscarCuentasAsiento, cambiarEstadoAsientoTipo, cambiarEstadoDetalleAsiento, guardarAsientoTipo, guardarDetalleAsiento, listarAsientosTipo, listarDetallesAsiento, obtenerOpcionesAsientosTipo } from '../services/asientosTipo'
import type { AsientoTipo, AsientoTipoDetalle, AsientoTipoOption, CuentaAsientoOption, OrigenAsientoOption } from '../interfaces/asientosTipo.interface'
const tipos=ref<AsientoTipoOption[]>([]),origenes=ref<OrigenAsientoOption[]>([]),asientos=ref<AsientoTipo[]>([]),detalles=ref<AsientoTipoDetalle[]>([]),tipoActivo=ref<AsientoTipoOption|null>(null),asientoActivo=ref<AsientoTipo|null>(null),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modalAsiento=ref(false),modalDetalle=ref(false),editAsiento=ref<number|null>(null),editDetalle=ref<number|null>(null),cuentaQuery=ref(''),cuentas=ref<CuentaAsientoOption[]>([]),buscando=ref(false)
const asientoForm=reactive({descripcion:'',origen_comprobante_id:0}),detalleForm=reactive<{cuenta_contable_id:number;cuenta_texto:string;naturaleza:'D'|'H';factor:number}>({cuenta_contable_id:0,cuenta_texto:'',naturaleza:'D',factor:1})
const msg=(v:unknown)=>v instanceof Error?v.message:'No se pudo completar la operación.'
async function init(){loading.value=true;try{const r=await obtenerOpcionesAsientosTipo();tipos.value=r.tipos_documento;origenes.value=r.origenes}catch(v){error.value=msg(v)}finally{loading.value=false}}
async function selectTipo(item:AsientoTipoOption){tipoActivo.value=item;asientoActivo.value=null;detalles.value=[];loading.value=true;try{asientos.value=await listarAsientosTipo(item.id)}catch(v){error.value=msg(v)}finally{loading.value=false}}
async function selectAsiento(item:AsientoTipo){asientoActivo.value=item;loading.value=true;try{detalles.value=await listarDetallesAsiento(item.id)}catch(v){error.value=msg(v)}finally{loading.value=false}}
function openAsiento(item?:AsientoTipo){editAsiento.value=item?.id??null;asientoForm.descripcion=item?.descripcion??'';asientoForm.origen_comprobante_id=item?.origen_comprobante_id??0;modalAsiento.value=true}
async function saveAsiento(){if(!tipoActivo.value||!asientoForm.descripcion.trim()||!asientoForm.origen_comprobante_id)return void(error.value='Complete descripción y origen.');saving.value=true;try{await guardarAsientoTipo(editAsiento.value,{tipo_documento:tipoActivo.value.id,descripcion:asientoForm.descripcion.trim().toUpperCase(),origen_comprobante_id:asientoForm.origen_comprobante_id});modalAsiento.value=false;success.value='Asiento guardado correctamente.';await selectTipo(tipoActivo.value)}catch(v){error.value=msg(v)}finally{saving.value=false}}
async function toggleAsiento(item:AsientoTipo){if(!confirm('¿Cambiar el estado del asiento?'))return;try{await cambiarEstadoAsientoTipo(item.id);if(tipoActivo.value)await selectTipo(tipoActivo.value)}catch(v){error.value=msg(v)}}
function openDetalle(item?:AsientoTipoDetalle){editDetalle.value=item?.id??null;detalleForm.cuenta_contable_id=item?.cuenta_contable_id??0;detalleForm.cuenta_texto=item?`${item.cta_contable??''} - ${item.cta_descripcion??''}`:'';detalleForm.naturaleza=item?.naturaleza??'D';detalleForm.factor=Number(item?.factor??1);cuentaQuery.value='';cuentas.value=[];modalDetalle.value=true}
async function searchAccounts(){if(!cuentaQuery.value.trim())return;buscando.value=true;try{cuentas.value=await buscarCuentasAsiento(cuentaQuery.value.trim())}catch(v){error.value=msg(v)}finally{buscando.value=false}}
function chooseAccount(item:CuentaAsientoOption){detalleForm.cuenta_contable_id=item.id;detalleForm.cuenta_texto=`${item.cta_contable} - ${item.descripcion}`;detalleForm.naturaleza=item.naturaleza;cuentas.value=[]}
async function saveDetalle(){if(!asientoActivo.value||!detalleForm.cuenta_contable_id)return void(error.value='Seleccione una cuenta contable.');if(detalleForm.factor<0||detalleForm.factor>999.99)return void(error.value='El factor debe estar entre 0 y 999.99.');saving.value=true;try{await guardarDetalleAsiento(editDetalle.value,{asiento_id:asientoActivo.value.id,cuenta_contable_id:detalleForm.cuenta_contable_id,naturaleza:detalleForm.naturaleza,factor:detalleForm.factor});modalDetalle.value=false;success.value='Detalle guardado correctamente.';await selectAsiento(asientoActivo.value)}catch(v){error.value=msg(v)}finally{saving.value=false}}
async function toggleDetalle(item:AsientoTipoDetalle){if(!confirm('¿Cambiar el estado del detalle?'))return;try{await cambiarEstadoDetalleAsiento(item.id);if(asientoActivo.value)await selectAsiento(asientoActivo.value)}catch(v){error.value=msg(v)}}
onMounted(init)
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/administracion/contabilidad">Contabilidad</RouterLink> / Asientos tipo</nav><header class="hero"><div class="mark">AT</div><div><small>MIA · CONTABILIDAD · MAESTROS</small><h1>Asientos tipo</h1><p>Configura asientos automáticos y sus cuentas según el tipo de documento.</p></div></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><main class="layout"><aside class="panel"><h2>Tipos de documento</h2><button v-for="item in tipos" :key="item.id" :class="{active:tipoActivo?.id===item.id}" @click="selectTipo(item)"><b>{{item.nombre}}</b><small>{{item.diminutivo||'Sin diminutivo'}}</small></button><p v-if="!tipos.length">No hay tipos disponibles.</p></aside><div class="content"><section class="panel"><header><div><h2>Asientos</h2><small>{{tipoActivo?.nombre||'Seleccione un tipo de documento'}}</small></div><button v-if="tipoActivo" @click="openAsiento()">+ Nuevo asiento</button></header><div class="scroll"><table><thead><tr><th>Item</th><th>Descripción</th><th>Origen</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-if="!asientos.length"><td colspan="5">{{loading?'Cargando…':'No hay asientos.'}}</td></tr><tr v-for="item in asientos" :key="item.id" :class="{selected:asientoActivo?.id===item.id}" @click="selectAsiento(item)"><td>{{item.nroitem}}</td><td>{{item.descripcion}}</td><td>{{item.origen_comprobante?.nombre||'—'}}</td><td><span :class="item.estado?'ok':'bad'">{{item.estado?'Activo':'Inactivo'}}</span></td><td class="actions"><button @click.stop="openAsiento(item)">Editar</button><button class="soft" @click.stop="toggleAsiento(item)">Estado</button></td></tr></tbody></table></div></section><section class="panel"><header><div><h2>Detalle del asiento</h2><small>{{asientoActivo?.descripcion||'Seleccione un asiento'}}</small></div><button v-if="asientoActivo" @click="openDetalle()">+ Nuevo detalle</button></header><div class="scroll"><table><thead><tr><th>Item</th><th>Cuenta</th><th>Descripción</th><th>D/H</th><th>Factor</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-if="!detalles.length"><td colspan="7">No hay detalles.</td></tr><tr v-for="item in detalles" :key="item.id"><td>{{item.nroitem}}</td><td>{{item.cta_contable||'—'}}</td><td>{{item.cta_descripcion||'—'}}</td><td>{{item.naturaleza}}</td><td>{{Number(item.factor).toFixed(2)}}</td><td><span :class="item.estado?'ok':'bad'">{{item.estado?'Activo':'Inactivo'}}</span></td><td class="actions"><button @click="openDetalle(item)">Editar</button><button class="soft" @click="toggleDetalle(item)">Estado</button></td></tr></tbody></table></div></section></div></main><div v-if="modalAsiento" class="backdrop" @mousedown.self="modalAsiento=false"><form class="dialog" @submit.prevent="saveAsiento"><header><h2>{{editAsiento?'Editar':'Nuevo'}} asiento</h2><button type="button" @click="modalAsiento=false">×</button></header><label>Descripción *<input v-model="asientoForm.descripcion" maxlength="100"></label><label>Origen *<select v-model="asientoForm.origen_comprobante_id"><option :value="0">Seleccione…</option><option v-for="o in origenes" :key="o.id" :value="o.id">{{o.nombre}}</option></select></label><footer><button type="button" class="soft" @click="modalAsiento=false">Cancelar</button><button :disabled="saving">Guardar</button></footer></form></div><div v-if="modalDetalle" class="backdrop" @mousedown.self="modalDetalle=false"><form class="dialog wide" @submit.prevent="saveDetalle"><header><h2>{{editDetalle?'Editar':'Nuevo'}} detalle</h2><button type="button" @click="modalDetalle=false">×</button></header><label>Cuenta contable *<input v-model="cuentaQuery" placeholder="Buscar por código o descripción" @keyup.enter.prevent="searchAccounts"><button type="button" @click="searchAccounts">{{buscando?'Buscando…':'Buscar cuenta'}}</button></label><div v-if="cuentas.length" class="results"><button v-for="c in cuentas" :key="c.id" type="button" @click="chooseAccount(c)"><b>{{c.cta_contable}}</b> {{c.descripcion}}</button></div><p v-if="detalleForm.cuenta_texto" class="chosen">✓ {{detalleForm.cuenta_texto}}</p><div class="fields"><label>Naturaleza<select v-model="detalleForm.naturaleza"><option value="D">Deudora</option><option value="H">Acreedora</option></select></label><label>Factor<input v-model.number="detalleForm.factor" type="number" min="0" max="999.99" step="0.01"></label></div><footer><button type="button" class="soft" @click="modalDetalle=false">Cancelar</button><button :disabled="saving">Guardar</button></footer></form></div></div></template>
<style scoped>
.page{--a:#385d8a;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--a);text-decoration:none}.hero{padding:20px;display:flex;gap:14px;align-items:center;border-left:5px solid var(--a);border-radius:12px;background:#fff}.mark{width:48px;height:48px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--a);font-weight:800}.hero small{color:var(--a);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.flash{padding:9px;border-radius:7px;font-size:.6rem}.success{color:#287052;background:#edf9f3}.error{color:#a64046;background:#fff0f0}.layout{margin-top:10px;display:grid;grid-template-columns:240px 1fr;gap:10px}.content{display:grid;gap:10px}.panel{overflow:hidden;border-radius:10px;background:#fff}.panel>h2,.panel>header{margin:0;padding:13px}.panel>h2,.panel h2{font-size:.72rem}.panel>button{width:100%;padding:11px;display:grid;border:0;border-top:1px solid #edf0f2;text-align:left;background:#fff;font-size:.55rem}.panel>button small,.panel header small{color:#87949a;font-size:.46rem}.panel>button.active{color:#fff;background:var(--a)}.panel>header{display:flex;align-items:center;justify-content:space-between}.panel>header h2{margin:0}.panel>header button,.dialog button{padding:8px 10px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.5rem}.scroll{overflow:auto}table{width:100%;min-width:680px;border-collapse:collapse;font-size:.5rem}th,td{padding:9px;border-top:1px solid #e8ecee;text-align:left}th{color:#fff;background:#4c627e}.selected{background:#eef4fa}.ok,.bad{padding:3px 6px;border-radius:10px}.ok{color:#287154;background:#e6f7ee}.bad{color:#9d4046;background:#fdebed}.actions{display:flex;gap:3px}.actions button{padding:5px;border:0;border-radius:4px;color:#385d8a;background:#e8eff8;font-size:.43rem}.soft{color:#64727a!important;background:#edf1f3!important}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(520px,100%);padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog.wide{width:min(700px,100%)}.dialog header{display:flex;justify-content:space-between}.dialog h2{margin:0 0 12px;font-size:.9rem}.dialog header button{color:#59666c;background:none;font-size:1.1rem}.dialog label{display:grid;margin-top:10px;gap:5px;font-size:.52rem}.dialog input,.dialog select{padding:9px;border:1px solid #d7dfe2;border-radius:6px;font:inherit;font-size:.55rem}.dialog footer{margin-top:16px;display:flex;justify-content:flex-end;gap:6px}.results{max-height:180px;overflow:auto}.results button{width:100%;display:block;color:#35464e;background:#f2f5f7;text-align:left}.chosen{padding:8px;color:#287154;background:#e6f7ee;font-size:.52rem}.fields{display:grid;grid-template-columns:1fr 1fr;gap:10px}@media(max-width:800px){.layout{grid-template-columns:1fr}.fields{grid-template-columns:1fr}}
</style>
